package cn.balltv.portal;
/** Conservative court-color check for thumbnails, not a person/ad classifier. */
public final class SportsPreview {
 public static boolean acceptable(int[] pixels,String sport){if(pixels==null||pixels.length<64)return false;sport=Events.sport(sport);int green=0,warm=0,blue=0,red=0;boolean[] greens=new boolean[512],warms=new boolean[512];for(int c:pixels){int r=(c>>16)&255,g=(c>>8)&255,b=c&255,bin=((r>>5)<<6)|((g>>5)<<3)|(b>>5);if(g>45&&g>r*1.12&&g>b*1.06){green++;greens[bin]=true;}if(r>75&&r>g*1.05&&g>b*.98&&r-b>25&&b>20){warm++;warms[bin]=true;}if(b>65&&b>r*1.2&&b>g*1.08)blue++;if(r>70&&r>g*1.4&&r>b*1.3)red++;}int gv=0,wv=0;for(boolean v:greens)if(v)gv++;for(boolean v:warms)if(v)wv++;float total=pixels.length;if(sport.equals("football"))return green/total>=.20f&&gv>=5&&spread(pixels);if(sport.equals("basketball"))return (warm/total>=.25f&&wv>=5||warm/total>=.16f&&green/total>=.08f&&wv>=5&&mixedCourt(pixels)||grayCourt(pixels))&&courtTexture(pixels);if(sport.equals("tennis"))return green/total>=.28f&&gv>=5||warm/total>=.3f&&wv>=5||blue/total>.45f&&red/total>.015f;if(sport.equals("snooker"))return green/total>.4f&&gv>=5;return false;}
 static boolean spread(int[] p){if(p.length!=48*27)return true;int[] green=new int[9];int centerSkin=0,center=0;for(int y=0;y<27;y++)for(int x=0;x<48;x++){int c=p[y*48+x],r=(c>>16)&255,g=(c>>8)&255,b=c&255;if(g>45&&g>r*1.12&&g>b*1.06)green[(y/9)*3+x/16]++;if(x>=16&&x<32&&y>=5&&y<23){center++;if(r>100&&g>65&&b>45&&r>g*1.08&&r>b*1.22&&r-g<80&&g-b<65)centerSkin++;}}int tiles=0;for(int n:green)if(n>28)tiles++;return tiles>=3&&centerSkin< center*.50f;}
 static boolean mixedCourt(int[] pixels){if(pixels.length!=48*27)return false;int[] tiles=new int[9];for(int y=9;y<27;y++)for(int x=0;x<48;x++){int c=pixels[y*48+x],r=c>>16&255,g=c>>8&255,b=c&255;if(r>75&&r>g*1.05&&g>b*.98&&r-b>25&&b>20)tiles[y/9*3+x/16]++;}int spread=0;for(int n:tiles)if(n>=18)spread++;return spread>=3;}
 static boolean neutralFloor(int c){int r=c>>16&255,g=c>>8&255,b=c&255;return g>70&&g<235&&Math.max(r,Math.max(g,b))-Math.min(r,Math.min(g,b))<35;}
 static boolean grayCourt(int[] pixels){if(pixels.length!=48*27)return false;int neutral=0;int[] marks=new int[9];for(int y=1;y<26;y++)for(int x=1;x<47;x++){int at=y*48+x,c=pixels[at],r=c>>16&255,g=c>>8&255,b=c&255;if(neutralFloor(c))neutral++;if(y<9||b<65||b<r*1.10||b<g*1.05)continue;for(int offset:new int[]{-1,1,-48,48}){int beside=pixels[at+offset];if(neutralFloor(beside)&&luma(beside)-luma(c)>15){marks[y/9*3+x/16]++;break;}}}int tiles=0;for(int count:marks)if(count>=2)tiles++;return neutral>pixels.length*.25f&&tiles>=3;}
 static int luma(int c){return (((c>>16)&255)*77+((c>>8)&255)*150+(c&255)*29)>>8;}
 static boolean courtTexture(int[] p){if(p.length!=48*27)return false;int edges=0,total=0;for(int y=9;y<26;y++)for(int x=1;x<47;x++){int at=y*48+x,v=luma(p[at]);if(Math.abs(v-luma(p[at-1]))>60||Math.abs(v-luma(p[at-48]))>60)edges++;total++;}return edges<total*.25f;}
}
